"""Hilfsfunktionen fuer konsistentes Fortschrittslogging."""

import logging
from collections.abc import Iterable, Iterator


def log_processing_start(logger: logging.Logger, total_records: int, description: str) -> None:
    """Loggt den Start einer Datensatzverarbeitung mit Gesamtanzahl."""
    logger.info("Starte %s: %s Datensaetze zu verarbeiten.", description, total_records)


def log_processing_progress(
    logger: logging.Logger,
    processed_records: int,
    total_records: int,
    description: str,
) -> None:
    """Loggt den Fortschritt einer Datensatzverarbeitung."""
    logger.info(
        "Fortschritt %s: %s/%s Datensaetze verarbeitet.",
        description,
        processed_records,
        total_records,
    )


def iter_with_progress[T](
    logger: logging.Logger,
    records: Iterable[T],
    total_records: int,
    description: str,
) -> Iterator[T]:
    """Iteriert ueber Datensaetze und loggt Start sowie Fortschritt je Datensatz."""
    log_processing_start(logger, total_records, description)
    for processed_records, record in enumerate(records, start=1):
        try:
            yield record
        finally:
            log_processing_progress(logger, processed_records, total_records, description)
